import os, signal


def killProcess(processID):
    '''
    Kill the process with the given processID.
    '''
    try:
        # Send SIGTERM to the process
        os.kill(processID, signal.SIGTERM)
        print(f"Sent SIGTERM to process {processID}")
    except OSError as e:
        if e.errno == 3:
            print(f"Process {processID} does not exist.")
        else:
            print(f"Failed to send SIGTERM to process {processID}: {e}")

    try:
        # Wait for the process to terminate
        os.waitpid(processID, 0)
        print(f"Process {processID} terminated successfully.")
    except OSError as e:
        if e.errno == 10:
            print(f"Process {processID} is already terminated.")
        else:
            print(f"Failed to wait for process {processID} to terminate: {e}")

